      "id": "road",
      "type": "line",
      "source": "osm",
      "source-layer": "transportation",
      "filter": ["==", "class", "primary"],
      "paint": { "line-color": "#ff0000", "line-width": 2 }
    },
    {
      "id": "building",
      "type": "fill",
      "source": "osm",
      "source-layer": "building",
      "paint": { "fill-color": "#f0f0f0", "fill-outline-color": "#999999" }
    }
  ]
}

